/**
 * @method
 * @name grvt#watchOrderBookForSymbols
 * @description watches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
 * @see https://api-docs.grvt.io/market_data_streams/#orderbook-snap
 * @see https://api-docs.grvt.io/market_data_streams/#orderbook-delta
 * @param {string[]} symbols unified array of symbols
 * @param {int} [limit] the maximum amount of order book entries to return.
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
 */
func (this *Grvt) WatchOrderBookForSymbolsAsync(symbols any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchOrderBookForSymbolsBody(ch, symbols, optionalArgs...)
	return ch
}
func (this *Grvt) watchOrderBookForSymbolsBody(ch chan any, symbols any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	limit := ccxt.GetArg(optionalArgs, 0, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var channel *string = nil
	var channelparamsVariable []any = this.HandleOptionStringAndParams(params, "watchOrderBook", "channel", "v1.book.d")
	channel = ccxt.SafeStringPtr(ccxt.GetValue(channelparamsVariable, 0))
	params = ccxt.MapTyped(ccxt.GetValue(channelparamsVariable, 1))
	var isSnapshot bool = (channel != nil && *channel == "v1.book.s")
	var symbolsLength int = ccxt.GetArrayLength(symbols)
	if symbolsLength == 0 {
		panic(ccxt.ArgumentsRequired(this.Id + " watchOrderBookForSymbols() requires a non-empty array of symbols"))
	}
	if limit == nil {
		var limitparamsVariable []any = this.HandleOptionIntegerAndParams(params, "watchOrderBook", "limit", 100)
		limit = ccxt.GetValue(limitparamsVariable, 0)
		params = ccxt.MapTyped(ccxt.GetValue(limitparamsVariable, 1))
	}
	var interval any = 500
	var intervalparamsVariable []any = this.HandleOptionIntegerAndParams(params, "watchOrderBook", "interval", interval)
	interval = ccxt.GetValue(intervalparamsVariable, 0)
	params = ccxt.MapTyped(ccxt.GetValue(intervalparamsVariable, 1))
	symbols = this.MarketSymbols(symbols)
	var extraPart any = func() any {
		if isSnapshot {
			return (ccxt.ToString(interval) + "-" + ccxt.ToString(limit))
		}
		return ccxt.ToString(interval)
	}()
	var rawHashes []any = []any{}
	var messageHashes []any = []any{}
	for i := 0; i < ccxt.GetArrayLength(symbols); i++ {
		var symbol *string = ccxt.SafeStringPtr(ccxt.GetValue(symbols, i))
		var market map[string]any = ccxt.MapTyped(this.Market(symbol))
		var marketId *string = ccxt.SafeStringPtr(market["id"])
		rawHashes = append(rawHashes, ccxt.Add(ccxt.Add(marketId, "@"), extraPart))
		messageHashes = append(messageHashes, ccxt.Add("orderbook::", market["symbol"]))
	}
	var request map[string]any = map[string]any{
		"stream":    channel,
		"selectors": rawHashes,
	}

	var orderbook ccxt.OrderBookInterface = ccxt.PanicOnError((<-this.SubscribeMultipleAsync(messageHashes, this.Extend(request, params), rawHashes))).(ccxt.OrderBookInterface)

	ch <- orderbook.(ccxt.OrderBookInterface).Limit()
	return nil
}
func (this *Grvt) HandleOrderBook(client any, message map[string]any) {
	//
	//    {
	//        "stream": "v1.book.s",
	//        "selector": "BTC_USDT_Perp@500-100",
	//        "sequence_number": "0",
	//        "feed": {
	//            "event_time": "1767292408400000000",
	//            "instrument": "BTC_USDT_Perp",
	//            "bids": [
	//                {
	//                    "price": "88107.3",
	//                    "size": "5.322",
	//                    "num_orders": 11
	//                },
	//            ],
	//            "asks": [
	//                {
	//                    "price": "88107.4",
	//                    "size": "5.273",
	//                    "num_orders": 37
	//                },
	//            ]
	//        },
	//        "prev_sequence_number": "0"
	//    }
	//
	var data map[string]any = ccxt.MapTyped(this.SafeDict(message, "feed", map[string]any{}))
	var selector *string = this.SafeString(message, "selector", "")
	var parts []string = strings.Split(*selector, "@")
	var marketId *string = this.SafeString(parts, 0)
	var market map[string]any = ccxt.MapTyped(this.SafeMarket(marketId))
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	var timestamp *int64 = this.SafeIntegerProduct(data, "event_time", 0.000001)
	if !(ccxt.InOp(this.Orderbooks, symbol)) {
		ccxt.AddElementToObject(this.Orderbooks, symbol, this.OrderBook())
	}
	var orderbook any = ccxt.GetValue(this.Orderbooks, symbol)
	var sequenceNumber *int64 = this.SafeInteger(message, "sequence_number", 0)
	var stream *string = this.SafeString(message, "stream")
	var isSnapshotChannel bool = (stream != nil && *stream == "v1.book.s")
	var isSnapshotMessage bool = (sequenceNumber == nil || *sequenceNumber <= 0)
	if isSnapshotChannel || isSnapshotMessage {
		var snapshot map[string]any = this.ParseOrderBook(data, symbol, timestamp, "bids", "asks", "price", "size")
		orderbook.(ccxt.OrderBookInterface).Reset(snapshot)
	} else {
		var asks []any = ccxt.SafeListTypedDefault(data, "asks", []any{})
		var bids []any = ccxt.SafeListTypedDefault(data, "bids", []any{})
		this.HandleDeltasWithKeys(ccxt.GetValue(orderbook, "asks"), asks, "price", "size")
		this.HandleDeltasWithKeys(ccxt.GetValue(orderbook, "bids"), bids, "price", "size")
		ccxt.AddElementToObject(orderbook, "timestamp", timestamp)
		ccxt.AddElementToObject(orderbook, "datetime", this.Iso8601(timestamp))
	}
	// grvt defaults to the delta channel (v1.book.d); if the very first
	// message is a delta, the freshly-created orderbook has symbol=null
	// because no snapshot has reset it yet. ccxt.Set it unconditionally — we
	// know the symbol from the selector regardless of channel. Java's
	// typed ccxt.WsOrderBook surfaces this as `"symbol":null` in the output
	// Python/JS dict-backed orderbooks happen to mask it but the
	// unconditional assignment is correct for every language.
	ccxt.AddElementToObject(orderbook, "symbol", symbol)
	ccxt.AddElementToObject(orderbook, "nonce", sequenceNumber)
	var messageHash string = "orderbook::" + *symbol
	ccxt.AddElementToObject(this.Orderbooks, symbol, orderbook)
	client.(ccxt.ClientInterface).Resolve(orderbook, messageHash)
}
func (this *Grvt) AuthenticateAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.authenticateBody(ch, optionalArgs...)
	return ch
}
func (this *Grvt) authenticateBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	this.CheckRequiredCredentials()

	ccxt.PanicOnError((<-this.SignInAsync()))
	var wsOptions map[string]any = ccxt.SafeMapTyped(this.Options, "ws")
	var authenticated *string = this.SafeString(wsOptions, "token")
	if authenticated == nil {
		var accountId *string = this.SafeString(this.Options, "AuthAccountId")
		var cookieValue *string = this.SafeString(this.Options, "AuthCookieValue")
		if (cookieValue == nil) || (accountId == nil) {
			panic(ccxt.AuthenticationError(this.Id + " : at first, you need to authenticate with exchange using signIn() method."))
		}
		var defaultOptions map[string]any = map[string]any{
			"ws": map[string]any{
				"options": map[string]any{
					"headers": map[string]any{
						"Cookie":            cookieValue,
						"X-Grvt-Account-Id": accountId,
					},
				},
			},
		}
		this.ExtendExchangeOptions(defaultOptions)
		this.Client(ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"), "privateTrading"))
	}
	return nil
}

/**
 * @method
 * @name grvt#watchMyTrades
 * @description watches information on multiple trades made by the user
 * @see https://api-docs.grvt.io/trading_streams/#fill
 * @param {string} symbol unified market symbol of the market trades were made in
 * @param {int} [since] the earliest time in ms to fetch trades for
 * @param {int} [limit] the maximum number of trade structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {boolean} [params.unifiedMargin] use unified margin account
 * @returns {object[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=trade-structure}
 */
func (this *Grvt) WatchMyTradesAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchMyTradesBody(ch, optionalArgs...)
	return ch
}
func (this *Grvt) watchMyTradesBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var symbol *string = ccxt.GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	limit := ccxt.GetArg(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}

	ccxt.PanicOnError((<-this.AuthenticateAsync()))
	var subAccountId any = this.GetSubAccountId(params)
	var messageHashes []any = []any{}
	var rawHashes []any = []any{}
	if symbol != nil {
		var market map[string]any = ccxt.MapTyped(this.Market(symbol))
		rawHashes = append(rawHashes, ccxt.Add(ccxt.Add(subAccountId, "-"), market["id"]))
		messageHashes = append(messageHashes, ccxt.Add("myTrades::", market["symbol"]))
	} else {
		messageHashes = append(messageHashes, "myTrades")
		rawHashes = append(rawHashes, subAccountId)
	}
	var request map[string]any = map[string]any{
		"stream":    "v1.fill",
		"selectors": rawHashes,
	}

	var trades ccxt.ArrayCacheInterface = ccxt.AsArrayCache(ccxt.PanicOnError((<-this.SubscribeMultipleAsync(messageHashes, this.Extend(request, params), messageHashes, false))))
	if this.NewUpdates {
		limit = ccxt.ToGetsLimit(trades).GetLimit(symbol, limit)
	}

	ch <- this.FilterBySinceLimit(trades, since, limit, "timestamp", true)
	return nil
}
func (this *Grvt) HandleMyTrade(client any, message map[string]any) {
	//
	//    {
	//        "stream": "v1.fill",
	//        "selector": "2147050003876484-BTC_USDT_Perp",
	//        "sequence_number": "1",
	//        "feed": {
	//            "event_time": "1767354369431470728",
	//            "sub_account_id": "2147050003876484",
	//            "instrument": "BTC_USDT_Perp",
	//            "is_buyer": true,
	//            "is_taker": true,
	//            "size": "0.001",
	//            "price": "89473.4",
	//            "mark_price": "89475.966335827",
	//            "index_price": "89515.016819765",
	//            "interest_rate": "0.0",
	//            "forward_price": "0.0",
	//            "realized_pnl": "0.0",
	//            "fee": "0.040263",
	//            "fee_rate": "0.045",
	//            "trade_id": "74150425-1",
	//            "order_id": "0x0101010503a12f6e000000007791f1bd",
	//            "venue": "ORDERBOOK",
	//            "is_liquidation": false,
	//            "client_order_id": "99191900",
	//            "signer": "0x42c9f56f2c9da534f64b8806d64813b29c62a01d",
	//            "broker": "UNSPECIFIED",
	//            "is_rpi": false,
	//            "builder": "0x00",
	//            "builder_fee_rate": "0.0",
	//            "builder_fee": "0"
	//        },
	//        "prev_sequence_number": "0"
	//    }
	//
	var data map[string]any = ccxt.MapTyped(this.SafeDict(message, "feed", map[string]any{}))
	if ccxt.IsEqual(this.MyTrades, nil) {
		var limit *int64 = this.SafeInteger(this.Options, "tradesLimit", 1000)
		this.MyTrades = ccxt.NewArrayCacheBySymbolById(limit)
	}
	var trade any = this.ParseWsMyTrade(data)
	this.MyTrades.(ccxt.Appender).Append(trade)
	client.(ccxt.ClientInterface).Resolve(this.MyTrades, ccxt.Add("myTrades::", ccxt.GetValue(trade, "symbol")))
	client.(ccxt.ClientInterface).Resolve(this.MyTrades, "myTrades")
}
func (this *Grvt) ParseWsMyTrade(trade map[string]any, optionalArgs ...any) any {
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	return this.ParseTrade(trade, market)
}

/**
 * @method
 * @name grvt#watchPositions
 * @see https://api-docs.grvt.io/trading_streams/#positions
 * @description watch all open positions
 * @param {string[]} [symbols] list of unified market symbols
 * @param {int} [since] the earliest time in ms to fetch positions for
 * @param {int} [limit] the maximum number of positions to retrieve
 * @param {object} params extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [position structure]{@link https://docs.ccxt.com/en/latest/manual.html#position-structure}
 */
func (this *Grvt) WatchPositionsAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchPositionsBody(ch, optionalArgs...)
	return ch
}
func (this *Grvt) watchPositionsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	symbols := ccxt.GetArg(optionalArgs, 0, nil)
	_ = symbols
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params

	ccxt.PanicOnError((<-this.AuthenticateAsync()))
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var subAccountId any = this.GetSubAccountId(params)
	symbols = this.MarketSymbols(symbols)
	var rawHashes []any = []any{}
	var messageHashes []any = []any{}
	if symbols != nil {
		for i := 0; i < ccxt.GetArrayLength(symbols); i++ {
			var symbol *string = ccxt.SafeStringPtr(ccxt.GetValue(symbols, i))
			var market map[string]any = ccxt.MapTyped(this.Market(symbol))
			rawHashes = append(rawHashes, ccxt.Add(ccxt.Add(subAccountId, "-"), market["id"]))
			messageHashes = append(messageHashes, ccxt.Add("positions::", market["symbol"]))
		}
	} else {
		messageHashes = append(messageHashes, "positions")
		rawHashes = append(rawHashes, subAccountId)
	}
	var request map[string]any = map[string]any{
		"stream":    "v1.position",
		"selectors": rawHashes,
	}

	newPositions := (<-this.SubscribeMultipleAsync(messageHashes, this.Extend(request, params), rawHashes, false))
	ccxt.PanicOnError(newPositions)
	if this.NewUpdates {

		ch <- newPositions
		return nil
	}

	ch <- this.FilterBySymbolsSinceLimit(this.Positions, symbols, since, limit, true)
	return nil
}
func (this *Grvt) HandlePosition(client any, message map[string]any) {
	//
	//    {
	//        "stream": "v1.position",
	//        "selector": "2147050003876484-BTC_USDT_Perp",
	//        "sequence_number": "0",
	//        "feed": {
	//            "event_time": "1767356959482262748",
	//            "sub_account_id": "2147050003876484",
	//            "instrument": "BTC_USDT_Perp",
	//            "size": "0.001",
	//            "notional": "89.430118",
	//            "entry_price": "89426.4",
	//            "exit_price": "0.0",
	//            "mark_price": "89430.118505969",
	//            "unrealized_pnl": "0.003718",
	//            "realized_pnl": "0.0",
	//            "total_pnl": "0.003718",
	//            "roi": "0.0041",
	//            "quote_index_price": "0.999101105",
	//            "est_liquidation_price": "74347.153505969",
	//            "leverage": "20.0",
	//            "cumulative_fee": "0.040241",
	//            "cumulative_realized_funding_payment": "0.0",
	//            "margin_type": "CROSS"
	//        },
	//        "prev_sequence_number": "0"
	//    }
	//
	if ccxt.IsEqual(this.Positions, nil) {
		this.Positions = ccxt.NewArrayCacheBySymbolBySide()
	}
	var data map[string]any = ccxt.SafeMapTyped(message, "feed")
	var position any = this.ParseWsPosition(data)
	var symbol *string = this.SafeString(position, "symbol")
	this.Positions.(ccxt.Appender).Append(position)
	var newPositions []any = []any{}
	newPositions = append(newPositions, position)
	client.(ccxt.ClientInterface).Resolve(newPositions, ccxt.Add("positions::", symbol))
	client.(ccxt.ClientInterface).Resolve(newPositions, "positions")
}
func (this *Grvt) ParseWsPosition(position any, optionalArgs ...any) any {
	// same as REST api
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	return this.ParsePosition(position, market)
}

/**
 * @method
 * @name grvt#watchOrders
 * @description watches information on multiple orders made by the user
 * @see https://api-docs.grvt.io/trading_streams/#order_1-feed-selector
 * @param {string} symbol unified market symbol of the market orders were made in
 * @param {int} [since] the earliest time in ms to fetch orders for
 * @param {int} [limit] the maximum number of order structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Grvt) WatchOrdersAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchOrdersBody(ch, optionalArgs...)
	return ch
}
func (this *Grvt) watchOrdersBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var symbol *string = ccxt.GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	limit := ccxt.GetArg(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}

	ccxt.PanicOnError((<-this.AuthenticateAsync()))
	var subAccountId any = this.GetSubAccountId(params)
	var messageHashes []any = []any{}
	var rawHashes []any = []any{}
	if symbol == nil {
		messageHashes = append(messageHashes, "orders")
		rawHashes = append(rawHashes, subAccountId)
	} else {
		var market map[string]any = ccxt.MapTyped(this.Market(symbol))
		messageHashes = append(messageHashes, ccxt.Add("order::", market["symbol"]))
		rawHashes = append(rawHashes, ccxt.Add(ccxt.Add(subAccountId, "-"), market["id"]))
	}
	var request map[string]any = map[string]any{
		"stream":    "v1.order",
		"selectors": rawHashes,
	}

	var orders ccxt.ArrayCacheInterface = ccxt.AsArrayCache(ccxt.PanicOnError((<-this.SubscribeMultipleAsync(messageHashes, this.Extend(request, params), rawHashes, false))))
	if this.NewUpdates {
		limit = ccxt.ToGetsLimit(orders).GetLimit(symbol, limit)
	}

	ch <- this.FilterBySymbolSinceLimit(orders, symbol, since, limit, true)
	return nil
}
func (this *Grvt) HandleOrder(client any, message map[string]any) {
	//
	//    {
	//        "stream": "v1.order",
	//        "selector": "2147050003876484",
	//        "sequence_number": "17",
	//        "feed": {
	//            "order_id": "0x010101050390cd89000000007799a374",
	//            "sub_account_id": "2147050003876484",
	//            "is_market": false,
	//            "time_in_force": "GOOD_TILL_TIME",
	//            "post_only": false,
	//            "reduce_only": false,
	//            "legs": [
	//                {
	//                    "instrument": "BTC_USDT_Perp",
	//                    "size": "0.001",
	//                    "limit_price": "87443.0",
	//                    "is_buying_asset": true
	//                }
	//            ],
	//            "signature": {
	//                "signer": "0x42c9f56f2c9da534f64b8806d64813b29c62a01d",
	//                "r": "0x4d2b96fdf384f9d8f050e3d72327813a7308969d11dba179eaec514c3427f059",
	//                "s": "0x42717bf56091606691a569d612f302ac27e51d41df840ae217dcd0310790cd89",
	//                "v": 28,
	//                "expiration": "1769951360245000000",
	//                "nonce": 747860882,
	//                "chain_id": "0"
	//            },
	//            "metadata": {
	//                "client_order_id": "747860882",
	//                "create_time": "1767359366686762920",
	//                "trigger": {
	//                    "trigger_type": "UNSPECIFIED",
	//                    "tpsl": {
	//                        "trigger_by": "UNSPECIFIED",
	//                        "trigger_price": "0.0",
	//                        "close_position": false
	//                    }
	//                },
	//                "broker": "UNSPECIFIED",
	//                "is_position_transfer": false,
	//                "allow_crossing": false
	//            },
	//            "state": {
	//                "status": "OPEN",
	//                "reject_reason": "UNSPECIFIED",
	//                "book_size": [
	//                    "0.001"
	//                ],
	//                "traded_size": [
	//                    "0.0"
	//                ],
	//                "update_time": "1767359366686762920",
	//                "avg_fill_price": [
	//                    "0.0"
	//                ]
	//            },
	//            "builder": "0x00",
	//            "builder_fee": "0.0"
	//        },
	//        "prev_sequence_number": "16"
	//    }
	//
	var data map[string]any = ccxt.SafeMapTyped(message, "feed")
	if ccxt.IsEqual(this.Orders, nil) {
		var limit *int64 = this.SafeInteger(this.Options, "ordersLimit", 1000)
		this.Orders = ccxt.NewArrayCacheBySymbolById(limit)
	}
	var order map[string]any = ccxt.MapTyped(this.ParseWsOrder(data))
	this.Orders.(ccxt.Appender).Append(order)
	client.(ccxt.ClientInterface).Resolve(this.Orders, "orders")
	client.(ccxt.ClientInterface).Resolve(this.Orders, ccxt.Add("order::", order["symbol"]))
}
func (this *Grvt) ParseWsOrder(order any, optionalArgs ...any) any {
	// same as REST api
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	return this.ParseOrder(order, market)
}
func (this *Grvt) HandleErrorMessage(client any, response any) any {
	//
	//    {
	//        "jsonrpc": "2.0",
	//        "error": {
	//            "code": 3000,
	//            "message": "Instrument is invalid"
	//        },
	//        "id": 1,
	//        "method": "subscribe"
	//    }
	//
	var error map[string]any = ccxt.SafeMapTyped(response, "error")
	var errorCode *string = this.SafeString(error, "code")
	if errorCode != nil {
		var body any = this.Json(response)
		var feedback any = ccxt.Add(this.Id+" ", body)
		var message *string = this.SafeString(error, "message")
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], errorCode, feedback)
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], message, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], message, feedback)
		panic(ccxt.ExchangeError(ccxt.Add(this.Id+" ", body)))
	}
	return false
}

func NewGrvt(userConfig map[string]any) *Grvt {
	p := newGrvt()
	p.Init(userConfig)
	return p
}

func (this *Grvt) Init(userConfig map[string]any) {
	this.base.Init(this.DeepExtend(this.Describe(), userConfig))
	this.Itf = this
	this.Exchange.DerivedExchange = this
}

